export default {
  'react-01': `function Greeting(){ return <h1 className="hello">Hello, React!</h1> }\nfunction App(){ return <Greeting /> }`,
  'react-02': `function StudentCard({ name, course, year = 1 }){ return <div className="card"><h2>{name}</h2><p>Course: {course} · Year {year}</p></div> }\nfunction App(){ return <StudentCard name="Ana" course="BSCS" year={3} /> }`,
  'react-03': `function Counter(){ const [c,setC]=useState(0); return <div><p id="value">Count: {c}</p><button id="inc" onClick={()=>setC(c+1)}>+</button><button id="dec" onClick={()=>setC(Math.max(0,c-1))}>-</button><button id="reset" onClick={()=>setC(0)}>Reset</button></div> }\nfunction App(){ return <Counter /> }`,
  'react-04': `function TaskList({ tasks }){ if(tasks.length===0) return <p className="empty">No tasks yet</p>; return <div><ul>{tasks.map(t=><li key={t.id} className={t.done?'done':''}>{t.title}</li>)}</ul><p className="summary">{tasks.filter(t=>t.done).length} of {tasks.length} done</p></div> }\nfunction App(){ return <TaskList tasks={[]} /> }`,
  'react-05': `function SignupForm(){ const [name,setName]=useState(''); return <form><input id="name" value={name} onChange={e=>setName(e.target.value)} /><p id="preview">Hello, {name.trim()||'stranger'}!</p><button type="submit" disabled={name.trim().length<3}>Sign up</button></form> }\nfunction App(){ return <SignupForm /> }`,
  'react-06': `function CourseList({ loadCourses }){ const [courses,setCourses]=useState(null); useEffect(()=>{ loadCourses().then(setCourses) },[]); useEffect(()=>{ if(courses) document.title = courses.length + ' courses' },[courses]); if(!courses) return <p className="loading">Loading…</p>; return <ul>{courses.map(c=><li key={c}>{c}</li>)}</ul> }\nfunction App(){ return <CourseList loadCourses={()=>Promise.resolve(['HTML','CSS'])} /> }`,
}
